<?php
// Contact box → Telegram bot.
// config.php is generated by the deploy workflow from GitHub Secrets (never committed; the repo is public).
// If no chat id is configured, the first person to press Start in the bot becomes the recipient
// (stored in data/chat_id.txt). Delete that file to connect a different chat.

header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');

function reply($ok, $msg, $code = 200) {
    http_response_code($code);
    echo json_encode(['ok' => $ok, 'message' => $msg]);
    exit;
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') reply(false, 'Use POST.', 405);

$cfgFile = __DIR__ . '/config.php';
if (!is_file($cfgFile)) reply(false, 'Messaging is not set up yet.', 503);
$cfg = require $cfgFile;
$token = trim($cfg['bot_token'] ?? '');
if ($token === '') reply(false, 'Messaging is not set up yet.', 503);

$dataDir = __DIR__ . '/data';

function tg($token, $method, $params) {
    $ch = curl_init("https://api.telegram.org/bot$token/$method");
    curl_setopt_array($ch, [
        CURLOPT_POST => true,
        CURLOPT_POSTFIELDS => http_build_query($params),
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 15,
    ]);
    $res = curl_exec($ch);
    curl_close($ch);
    return $res ? json_decode($res, true) : null;
}

// --- input ---
$text    = trim((string)($_POST['message'] ?? ''));
$contact = trim((string)($_POST['contact'] ?? ''));
$trap    = trim((string)($_POST['website'] ?? ''));   // hidden field; bots fill it
if ($trap !== '') reply(true, 'Thanks, message sent.');
if ($text === '') reply(false, 'Please write a message.', 400);
if (mb_strlen($text) > 3000) reply(false, 'Message is too long (max 3000 characters).', 400);
if (mb_strlen($contact) > 200) reply(false, 'Contact is too long.', 400);

// --- simple rate limit: 5 messages per 10 minutes per IP ---
$ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
$rlFile = $dataDir . '/rate.json';
$now = time();
$fp = fopen($rlFile, 'c+');
if ($fp) {
    flock($fp, LOCK_EX);
    $rl = json_decode(stream_get_contents($fp), true) ?: [];
    foreach ($rl as $k => $times) {
        $rl[$k] = array_values(array_filter($times, fn($t) => $t > $now - 600));
        if (!$rl[$k]) unset($rl[$k]);
    }
    $key = hash('sha256', $ip);
    if (count($rl[$key] ?? []) >= 5) {
        flock($fp, LOCK_UN); fclose($fp);
        reply(false, 'Too many messages. Please try again in a few minutes.', 429);
    }
    $rl[$key][] = $now;
    ftruncate($fp, 0); rewind($fp); fwrite($fp, json_encode($rl));
    flock($fp, LOCK_UN); fclose($fp);
}

// --- find the chat to send to ---
$chatId = trim((string)($cfg['chat_id'] ?? ''));
$chatFile = $dataDir . '/chat_id.txt';
if ($chatId === '' && is_file($chatFile)) $chatId = trim(file_get_contents($chatFile));
if ($chatId === '') {
    $upd = tg($token, 'getUpdates', ['limit' => 100]);
    foreach (($upd['result'] ?? []) as $u) {
        $chat = $u['message']['chat'] ?? null;
        if ($chat && ($chat['type'] ?? '') === 'private') { $chatId = (string)$chat['id']; break; }
    }
    if ($chatId === '') reply(false, 'Messaging is not connected yet.', 503);
    file_put_contents($chatFile, $chatId);
    tg($token, 'sendMessage', ['chat_id' => $chatId,
        'text' => "✅ This chat is now connected to the message box on kasparsleitis.com."]);
}

// --- send ---
$body = "📩 New message from kasparsleitis.com\n\n" . $text;
if ($contact !== '') $body .= "\n\n👤 Contact: " . $contact;
$body .= "\n\n🕒 " . (new DateTime('now', new DateTimeZone('Europe/Riga')))->format('Y-m-d H:i');

$res = tg($token, 'sendMessage', ['chat_id' => $chatId, 'text' => $body, 'disable_web_page_preview' => 'true']);
if (!($res['ok'] ?? false)) reply(false, 'Could not send the message. Please try again later.', 502);
reply(true, 'Thanks, message sent.');
